mapper.delete:
/* ExecLogPurgeBatchMapper.deleteBatchStepExecution 기준일시 이전 Step 실행 정보를 삭제한다. */
DELETE FROM BATCH_STEP_EXECUTION
 WHERE JOB_EXECUTION_ID IN ()

/* ExecLogPurgeBatchMapper.deleteBatchJobExecutionContext 기준일시 이전 Job 실행 컨텍스트를 삭제한다. */
DELETE FROM BATCH_JOB_EXECUTION_CONTEXT
 WHERE JOB_EXECUTION_ID IN ()

/* ExecLogPurgeBatchMapper.deleteBatchJobExecutionParams 기준일시 이전 Job 실행 파라미터를 삭제한다. */
DELETE FROM BATCH_JOB_EXECUTION_PARAMS
 WHERE JOB_EXECUTION_ID IN ()

/* ExecLogPurgeBatchMapper.deleteBatchJobExecution 기준일시 이전 Job 실행 정보를 삭제한다. */
DELETE FROM BATCH_JOB_EXECUTION
 WHERE JOB_EXECUTION_ID IN ()

/* ExecLogPurgeBatchMapper.deleteDsptExecLog 기준일시 이전 배치실행내역(TB_DSPT_EXEC_L)을 삭제한다. */
DELETE FROM TB_DSPT_EXEC_L
 WHERE EXEC_ST_DTTM < #{baseDttm}
   AND EXEC_END_DTTM IS NOT NULL
